import SwiftUI
#if canImport(UIKit)
import UIKit
#endif

/// Brand art that ships with LKDesign. Nothing here draws or recolours anything: the logo is the asset catalog's `LexkiteMark`
/// (the exact brand/lexkite-mark.svg, generated by scripts/native/gen.mjs), the teacher is the web's 2D Ama art.
public enum LKBrand {
    public static let bundle = Bundle.module
}

/// The Lexkite mark, exactly as in the brand kit (vector, no tint, no redraw).
public struct LexkiteMark: View {
    let size: CGFloat
    public init(size: CGFloat) { self.size = size }
    public var body: some View {
        Image("LexkiteMark", bundle: LKBrand.bundle).renderingMode(.original).resizable().scaledToFit()
            .frame(width: size, height: size)
            .accessibilityHidden(true)
    }
}

#if canImport(UIKit)
/// Teacher stills = web `Chars.still(who, pose)` (web/teach/characters.json, `teach/<who>/still-<pose>.webp`). Order: bundled copy (instant, offline, the
/// poses onboarding uses are generated into the package from the same web files) → disk cache → CDN (same URL as web), then cached.
public enum TeacherArt {
    public static let base = URL(string: "https://lexkite.com/teach/")!

    public static func bundledURL(who: String, pose: String) -> URL? {
        LKBrand.bundle.url(forResource: "still-\(pose)", withExtension: "webp", subdirectory: "teach/\(who)")
    }
    public static func bundled(who: String, pose: String) -> UIImage? {
        bundledURL(who: who, pose: pose).flatMap { try? Data(contentsOf: $0) }.flatMap { UIImage(data: $0) }
    }
    static func cacheURL(who: String, pose: String) -> URL? {
        FileManager.default.urls(for: .cachesDirectory, in: .userDomainMask).first?.appendingPathComponent("teach/still-\(who)-\(pose).webp")
    }
    public static func load(who: String, pose: String, session: URLSession = .shared) async -> UIImage? {
        if let b = bundled(who: who, pose: pose) { return b }
        if let c = cacheURL(who: who, pose: pose), let d = try? Data(contentsOf: c), let i = UIImage(data: d) { return i }
        var req = URLRequest(url: base.appendingPathComponent("\(who)/still-\(pose).webp")); req.timeoutInterval = 8
        guard let (data, resp) = try? await session.data(for: req), (resp as? HTTPURLResponse)?.statusCode == 200, let img = UIImage(data: data) else { return nil }
        if let c = cacheURL(who: who, pose: pose) { try? FileManager.default.createDirectory(at: c.deletingLastPathComponent(), withIntermediateDirectories: true); try? data.write(to: c) }
        return img
    }
}

/// Teacher still, bottom-aligned. Shows the bundled art on the very first frame (no flash, no network) when the pose is bundled.
public struct TeacherStill: View {
    let who: String, pose: String
    @State private var image: UIImage?
    public init(who: String = "ama", pose: String = "happy") {
        self.who = who; self.pose = pose
        _image = State(initialValue: TeacherArt.bundled(who: who, pose: pose))
    }
    public var body: some View {
        Group {
            if let image { Image(uiImage: image).resizable().scaledToFit() } else { Color.clear }
        }
        .task(id: pose) { if image == nil { image = await TeacherArt.load(who: who, pose: pose) } }
        .accessibilityHidden(true)
    }
}
#endif
